package com.selimhorri.app.business.auth.service.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.web.client.RestTemplate;
import com.selimhorri.app.business.user.model.CredentialDto;
import com.selimhorri.app.business.user.model.RoleBasedAuthority;
import com.selimhorri.app.business.user.model.UserDetailsImpl;

@ExtendWith(MockitoExtension.class)
class UserDetailsServiceImplTest {

    @Mock
    private RestTemplate restTemplate;

    @InjectMocks
    private UserDetailsServiceImpl service;

    // GreyTest trace: loadUserByUsername | credential fetch and UserDetailsImpl construction | BR-045 -> TP-034 -> TC-1453
    @Test
    void loadUserByUsername_FetchesCredentialAndBuildsUserDetails() {
        // Arrange
        String username = "alice";
        String url = "http://USER-SERVICE/user-service/api/credentials/username/alice";
        CredentialDto credential = new CredentialDto();
        credential.setCredentialId(1001);
        credential.setUsername("alice");
        credential.setPassword("valid-password");
        credential.setRoleBasedAuthority(RoleBasedAuthority.ROLE_USER);
        credential.setIsEnabled(true);
        credential.setIsAccountNonExpired(true);
        credential.setIsAccountNonLocked(true);
        credential.setIsCredentialsNonExpired(true);
        when(restTemplate.getForObject(url, CredentialDto.class)).thenReturn(credential);

        // Act
        UserDetailsImpl result = (UserDetailsImpl) service.loadUserByUsername(username);

        // Assert
        assertEquals("alice", result.getUsername());
        assertEquals("valid-password", result.getPassword());
        assertEquals("ROLE_USER", result.getAuthorities().iterator().next().getAuthority());
        assertTrue(result.isEnabled());
        assertTrue(result.isAccountNonExpired());
        assertTrue(result.isAccountNonLocked());
        assertTrue(result.isCredentialsNonExpired());
        verify(restTemplate).getForObject(url, CredentialDto.class);
    }
}
